param([ValidateSet('Full','Refresh')][string]$Mode='Full',[string]$TokenPath=(Join-Path $env:LOCALAPPDATA 'AGM\secrets\gmail-oauth-token.dpapi'))
$ErrorActionPreference='Stop';if(!(Test-Path -LiteralPath $TokenPath)){throw 'GMAIL_OAUTH_DPAPI_TOKEN_MISSING'}
$encrypted=[IO.File]::ReadAllText($TokenPath,[Text.Encoding]::UTF8);$secure=ConvertTo-SecureString $encrypted;$ptr=[Runtime.InteropServices.Marshal]::SecureStringToBSTR($secure)
try{$raw=[Runtime.InteropServices.Marshal]::PtrToStringBSTR($ptr);$bundle=$raw|ConvertFrom-Json;$env:GMAIL_OAUTH_CLIENT_ID=$bundle.client_id;$env:GMAIL_OAUTH_CLIENT_SECRET=$bundle.client_secret;$env:GMAIL_OAUTH_REFRESH_TOKEN=$bundle.refresh_token;$env:GMAIL_FROM_ADDRESS=$bundle.from_address;$env:GMAIL_E2E_MODE=if($Mode-eq'Refresh'){'refresh'}else{'full'};& pnpm.cmd --filter '@agm/api' exec ts-node scripts/test-gmail-external-e2e.ts;if($LASTEXITCODE-ne 0){exit $LASTEXITCODE}}finally{[Runtime.InteropServices.Marshal]::ZeroFreeBSTR($ptr);$raw=$null;$bundle=$null;$secure=$null;$encrypted=$null;$env:GMAIL_OAUTH_CLIENT_ID=$null;$env:GMAIL_OAUTH_CLIENT_SECRET=$null;$env:GMAIL_OAUTH_REFRESH_TOKEN=$null;$env:GMAIL_FROM_ADDRESS=$null;$env:GMAIL_E2E_MODE=$null}
